+.avatar-preview {
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+    margin-bottom: 1.5rem;
+    padding: 1rem;
+    background: #f8f9fa;
+    border-radius: 8px;
+}
+
+.avatar-image {
+    width: 80px;
+    height: 80px;
+    border-radius: 50%;
+    object-fit: cover;
+    background: #dee2e6;
+}
+
+.avatar-url {
+    font-size: 0.85rem;
+    color: #6c757d;
+    word-break: break-all;
+}
+
