+    font-weight: 600;
+    font-size: 0.85rem;
+    color: #555;
+}
+
+.current-badge {
+    font-size: 0.8rem;
+    color: #198754;
+    font-weight: 500;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
