+    width: 90%;
+    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
+}
+
+.modal-dialog h4 {
+    margin-top: 0;
+}
+
+.modal-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.25rem;
+}
+
+/* Radio group */
+.radio-group {
+    display: flex;
+    gap: 1.25rem;
+}
+
+.radio-item {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+/* Appearance preview */
+.preview-area {
+    margin-top: 1.5rem;
+    padding: 1.25rem;
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    transition: all 0.3s;
+}
+
+.preview-area.theme-dark {
+    background: #1e1e1e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-area.theme-light {
+    background: #ffffff;
+    color: #333;
+}
+
+.preview-area.theme-system {
+    background: #f8f9fa;
+    color: #333;
+}
+
+.preview-area.font-small {
+    font-size: 0.8rem;
+}
+
+.preview-area.font-medium {
+    font-size: 1rem;
+}
+
+.preview-area.font-large {
+    font-size: 1.2rem;
+}
+
+.preview-area.compact {
+    padding: 0.6rem;
+    line-height: 1.2;
+}
+
+.preview-card {
+    margin-top: 0.75rem;
+    padding: 0.75rem;
+    border: 1px solid currentColor;
+    border-radius: 4px;
+    opacity: 0.8;
+}
